import 'package:material_ui/material_ui.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../data/alert_repository.dart';import '../../auth/presentation/auth_controller.dart';final alertRepositoryProvider=Provider((ref)=>AlertRepository(ref.watch(apiClientProvider)));final alertsProvider=FutureProvider.autoDispose((ref)=>ref.watch(alertRepositoryProvider).all());class AlertsPage extends ConsumerWidget{const AlertsPage({super.key});@override Widget build(BuildContext context,WidgetRef ref){final a=ref.watch(alertsProvider);return Scaffold(appBar:AppBar(title:const Text('التنبيهات')),body:a.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(_,_)=>Center(child:FilledButton(onPressed:()=>ref.invalidate(alertsProvider),child:const Text('إعادة المحاولة'))),data:(items)=>items.isEmpty?const Center(child:Text('لا توجد تنبيهات.')):ListView.builder(itemCount:items.length,itemBuilder:(_,i)=>ListTile(title:Text(items[i].message),subtitle:Text(items[i].createdAt.toString()),trailing:items[i].read?null:const Icon(Icons.warning_amber),onTap:()async{if(!items[i].read){await ref.read(alertRepositoryProvider).read(items[i].id);ref.invalidate(alertsProvider);}})));}}